  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
  <style>
    :root{--bg:#f7f9fc;--card:#ffffff;--ink:#13233a;--muted:#4d5d75;--accent:#2457ff;--accent2:#00a3a3;--danger:#c93b3b;--ok:#1f8f4d;--warn:#d17b00;--grid:#d9e2ef}
    body{margin:0;font-family:Inter,Segoe UI,Roboto,Arial,sans-serif;background:var(--bg);color:var(--ink)}
    .wrap{max-width:1180px;margin:24px auto;padding:0 20px 36px}
    h1{font-size:30px;margin:0 0 6px}
    h2{font-size:22px;margin:0 0 12px}
    h3{font-size:18px;margin:0 0 8px}
    p{line-height:1.5;color:var(--muted)}
    .sub{font-size:14px;color:var(--muted);margin-bottom:20px}
    .grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}
    .card{background:var(--card);border:1px solid #e7edf7;border-radius:14px;padding:16px;box-shadow:0 2px 8px rgba(19,35,58,.04)}
    .kpi{grid-column:span 3}
    .kpi .v{font-weight:700;font-size:28px;margin-top:8px}
    .wide{grid-column:span 12}
    .half{grid-column:span 6}
    .takeaways li{margin:8px 0;color:#21344f}
    table{width:100%;border-collapse:collapse;font-size:14px}
    th,td{border-bottom:1px solid #ecf1f8;padding:8px;text-align:right}
    th:first-child,td:first-child{text-align:left}
    th{background:#f4f7fd;color:#30435f}
    .tag{display:inline-block;background:#edf3ff;color:#2852c7;padding:4px 8px;border-radius:999px;font-size:12px}
  </style>
</head>
<body>
<div class="wrap">
  <h1>Generative AI Competitive Landscape: User Sentiment & Complaint Analysis</h1>
  <div class="sub">Q1 2026 • Audience: Product Strategy Team • Source: `/app/benchmark/data.csv`</div>

  <section class="card wide">
    <h2>Executive Overview</h2>
    <div class="grid">
      <div class="card kpi"><div class="tag">Dataset</div><div class="v" id="k_total"></div><p>Total reviews analyzed across 5 apps</p></div>
      <div class="card kpi"><div class="tag">Satisfaction</div><div class="v" id="k_star"></div><p>Overall average star rating</p></div>
      <div class="card kpi"><div class="tag">Text Sentiment</div><div class="v" id="k_sent"></div><p>Overall mean sentiment polarity</p></div>
      <div class="card kpi"><div class="tag">Mismatch</div><div class="v" id="k_mismatch"></div><p>Star-vs-text contradiction rate</p></div>
    </div>
    <h3 style="margin-top:14px">Top 3 Strategic Takeaways</h3>
    <ol class="takeaways" id="top3"></ol>
  </section>

  <section class="grid" style="margin-top:14px">
    <div class="card half"><h2>Cross-App Sentiment Comparison</h2><canvas id="sentimentBar" height="220"></canvas></div>
    <div class="card half"><h2>Rating Distribution by App</h2><canvas id="ratingStack" height="220"></canvas></div>
  </section>

  <section class="grid" style="margin-top:14px">
    <div class="card half"><h2>Thematic Complaint Analysis by Application</h2><canvas id="themeStack" height="240"></canvas></div>
    <div class="card half"><h2>Complaint Hotspots (Pricing/Bugs/Accuracy)</h2><canvas id="complaintHeat" height="240"></canvas></div>
  </section>

  <section class="grid" style="margin-top:14px">
    <div class="card half"><h2>Sentiment-Rating Divergence & Sarcasm Detection</h2><canvas id="mismatchBar" height="220"></canvas>
      <p id="mismatchText"></p>
    </div>
    <div class="card half"><h2>Review Depth & Emotional Intensity</h2><canvas id="depthScatter" height="220"></canvas>
      <p id="depthText"></p>
    </div>
  </section>

  <section class="card wide" style="margin-top:14px">
    <h2>KPI Table</h2>
    <table id="kpiTable"></table>
  </section>

  <section class="card wide" style="margin-top:14px">
    <h2>Strategic Recommendations</h2>
    <ol id="recs" class="takeaways"></ol>
  </section>
</div>
<script>
const reportData = __DATA__;
const appOrder = reportData.summary.map(r=>r.App);
const byApp = Object.fromEntries(reportData.summary.map(r=>[r.App,r]));

const fmt=(n,d=2)=>Number(n).toFixed(d);
document.getElementById('k_total').textContent = reportData.global.total_reviews.toLocaleString();
document.getElementById('k_star').textContent = fmt(reportData.global.overall_avg_star,2);
document.getElementById('k_sent').textContent = fmt(reportData.global.overall_mean_sentiment,3);
document.getElementById('k_mismatch').textContent = fmt(reportData.global.overall_mismatch_rate,2)+'%';

const starLeader=[...reportData.summary].sort((a,b)=>b.Avg_Star-a.Avg_Star)[0];
const starTrailer=[...reportData.summary].sort((a,b)=>a.Avg_Star-b.Avg_Star)[0];
const mismatchWorst=[...reportData.summary].sort((a,b)=>b.Mismatch_Rate-a.Mismatch_Rate)[0];
const pricingWorst=[...reportData.summary].sort((a,b)=>(b.Theme_Distribution['Pricing/Subscription']||0)-(a.Theme_Distribution['Pricing/Subscription']||0))[0];

const top3=[
  `${starLeader.App} leads satisfaction (avg ${fmt(starLeader.Avg_Star)} stars; sentiment ${fmt(starLeader.Mean_Sentiment,3)}), while ${starTrailer.App} trails (${fmt(starTrailer.Avg_Star)} stars).`,
  `${mismatchWorst.App} shows the highest sentiment-rating mismatch (${fmt(mismatchWorst.Mismatch_Rate)}%), signaling greater sarcasm/complex-emotion distortion risk in star-only tracking.`,
  `${pricingWorst.App} has the highest pricing friction (${fmt(pricingWorst.Theme_Distribution['Pricing/Subscription']||0)}% pricing-tagged reviews); complaint themes also receive higher helpful-vote engagement than general reviews.`
];
document.getElementById('top3').innerHTML=top3.map(t=>`<li>${t}</li>`).join('');

new Chart(document.getElementById('sentimentBar'),{type:'bar',data:{labels:appOrder,datasets:[{label:'Avg Star',data:appOrder.map(a=>byApp[a].Avg_Star),yAxisID:'y',backgroundColor:'#2457ff'},{label:'Mean Sentiment',data:appOrder.map(a=>byApp[a].Mean_Sentiment),yAxisID:'y1',backgroundColor:'#00a3a3'}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{min:0,max:5,title:{display:true,text:'Stars'}},y1:{position:'right',min:-1,max:1,grid:{drawOnChartArea:false},title:{display:true,text:'Sentiment'}}}}});

const ratingDist=reportData.rating_dist;
new Chart(document.getElementById('ratingStack'),{type:'bar',data:{labels:appOrder,datasets:[1,2,3,4,5].map((s,i)=>({label:`${s}-Star`,data:appOrder.map(a=>ratingDist[a][String(s)]),backgroundColor:['#c93b3b','#e56a54','#d8b14d','#66a8ff','#1f8f4d'][i]}))},options:{plugins:{legend:{position:'bottom'}},responsive:true,scales:{x:{stacked:true},y:{stacked:true}}}});

const themes=['General','Pricing/Subscription','Bugs/Performance','Accuracy/Logic Issues'];
new Chart(document.getElementById('themeStack'),{type:'bar',data:{labels:appOrder,datasets:themes.map((t,i)=>({label:t,data:appOrder.map(a=>byApp[a].Theme_Distribution[t]||0),backgroundColor:['#9fb0c9','#d17b00','#c93b3b','#6f56d9'][i]}))},options:{plugins:{legend:{position:'bottom'}},responsive:true,scales:{x:{stacked:true},y:{stacked:true,max:100,title:{display:true,text:'% of reviews'}}}}});

new Chart(document.getElementById('complaintHeat'),{type:'bar',data:{labels:appOrder,datasets:[{label:'Pricing %',data:appOrder.map(a=>byApp[a].Theme_Distribution['Pricing/Subscription']||0),backgroundColor:'#d17b00'},{label:'Bugs %',data:appOrder.map(a=>byApp[a].Theme_Distribution['Bugs/Performance']||0),backgroundColor:'#c93b3b'},{label:'Accuracy %',data:appOrder.map(a=>byApp[a].Theme_Distribution['Accuracy/Logic Issues']||0),backgroundColor:'#6f56d9'}]},options:{indexAxis:'y',plugins:{legend:{position:'bottom'}},responsive:true}});

new Chart(document.getElementById('mismatchBar'),{type:'bar',data:{labels:appOrder,datasets:[{label:'Mismatch Rate %',data:appOrder.map(a=>byApp[a].Mismatch_Rate),backgroundColor:'#2457ff'}]},options:{plugins:{legend:{display:false}},responsive:true,scales:{y:{title:{display:true,text:'% contradictory reviews'}}}}});
document.getElementById('mismatchText').textContent=`Mismatch is computed as (4-5 star with negative sentiment) OR (1-2 star with positive sentiment). Highest: ${mismatchWorst.App} (${fmt(mismatchWorst.Mismatch_Rate)}%); lowest: ${[...reportData.summary].sort((a,b)=>a.Mismatch_Rate-b.Mismatch_Rate)[0].App} (${fmt([...reportData.summary].sort((a,b)=>a.Mismatch_Rate-b.Mismatch_Rate)[0].Mismatch_Rate)}%).`;

new Chart(document.getElementById('depthScatter'),{type:'scatter',data:{datasets:[{label:'App points: Avg Word Count vs Avg Sentiment',data:appOrder.map(a=>({x:byApp[a].Avg_Word_Count,y:byApp[a].Mean_Sentiment,app:a})),pointRadius:6,backgroundColor:'#00a3a3'}]},options:{plugins:{tooltip:{callbacks:{label:(ctx)=>`${ctx.raw.app}: words ${fmt(ctx.raw.x,1)}, sentiment ${fmt(ctx.raw.y,3)}`}}},scales:{x:{title:{display:true,text:'Average Word Count'}},y:{title:{display:true,text:'Average Sentiment'},min:-1,max:1}}}});

document.getElementById('depthText').textContent='Across all apps, review length correlates negatively with star rating and sentiment (longer reviews are generally more negative), while helpful-vote counts correlate positively with review length.';

const headers=['App','Avg Star','Mean Sentiment','Pricing %','Bugs %','Accuracy %','Mismatch %','Avg Thumbs Up','Avg Word Count'];
let html='<tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr>';
for(const a of appOrder){
  const r=byApp[a];
  html += `<tr><td>${a}</td><td>${fmt(r.Avg_Star)}</td><td>${fmt(r.Mean_Sentiment,3)}</td><td>${fmt(r.Theme_Distribution['Pricing/Subscription']||0)}</td><td>${fmt(r.Theme_Distribution['Bugs/Performance']||0)}</td><td>${fmt(r.Theme_Distribution['Accuracy/Logic Issues']||0)}</td><td>${fmt(r.Mismatch_Rate)}</td><td>${fmt(r.Avg_Thumbs_Up)}</td><td>${fmt(r.Avg_Word_Count,1)}</td></tr>`;
}
document.getElementById('kpiTable').innerHTML=html;

const recs=[
  `Prioritize anti-friction onboarding and reliability messaging against ${starLeader.App}, which currently sets the satisfaction benchmark.`,
  `Build a dedicated “Trust & Accuracy” roadmap narrative: apps with elevated accuracy complaints risk churn despite moderate ratings.`,
  `Treat mismatch-heavy app segments as a separate monitoring stream (NLP-first), because star averages understate sentiment volatility.`,
  `Use pricing-packaging experiments where pricing complaint share is highest (notably ${pricingWorst.App}) to reduce subscription resistance.`,
  `Route high-engagement complaint themes (bugs/pricing) into fast-response product ops, since these topics attract disproportionate community validation.`,
  `Track review-length inflation as an early warning for dissatisfaction; longer reviews in this dataset are systematically more negative.`
];
document.getElementById('recs').innerHTML=recs.map(r=>`<li>${r}</li>`).join('');
</script>
</body>
</html>
